// Normalise + validate inputs from either the public form or the MCP/sub-workflow trigger.
const input = $input.first().json;
const rawCaseId = input.case_id ?? input['Case ID'] ?? '';
const caseId = Number(rawCaseId);
const signalType = String(input.signal_type ?? input['Signal type'] ?? '').trim();
const evidenceUrl = String(input.evidence_url ?? input['Evidence URL'] ?? '').trim() || null;
const notes = String(input.notes ?? input['Notes'] ?? '').trim() || null;
const submittedBy = String(input.submitted_by ?? input['Submitted by'] ?? '').trim();

if (!Number.isInteger(caseId) || caseId <= 0) {
  throw new Error('case_id must be a positive numeric car_cases.case_id');
}
if (!signalType) {
  throw new Error('signal_type is required');
}
if (!submittedBy) {
  throw new Error('submitted_by is required');
}

const preDD = ['kyc_ready', 'references_ready', 'meetings_ready', 'ra01_ready',
               'ra02_ready', 'ra03_ready', 'ra04_ready', 'ra05_ready',
               'ra06_ready', 'afp_ready', 'documents_ready'];
const postDD = ['letter_signed', 'payment_received', 'loa_signed',
                'contracts_executed'];
const isPreDD = preDD.includes(signalType);
const isPostDD = postDD.includes(signalType);
if (!isPreDD && !isPostDD) {
  throw new Error('unknown signal_type: ' + signalType);
}

return [{
  json: {
    case_id: caseId,
    signal_type: signalType,
    evidence_url: evidenceUrl,
    notes,
    submitted_by: submittedBy,
    is_pre_dd: isPreDD,
    is_post_dd: isPostDD,
  }
}];

